findings.codeql_raw_query:
/**
 * @name Path traversal vulnerability
 * @description User input flowing to file operations without proper path validation
 * @kind path-problem
 * @problem.severity error
 * @id py/path-traversal
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.ApiGraphs
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(API::CallNode call |
      // File open operations
      sink = call.getArg(0) and
      (
        // builtin open
        call = API::builtin("open").getACall() or
        // os module file operations
        call = API::moduleImport("os").getMember(["open", "chmod", "chown", "stat", "lstat", "remove", "unlink", "rename", "listdir"]).getACall() or
        call = API::moduleImport("os").getMember(["path", "join"]).getACall() or
        // pathlib operations
        call = API::moduleImport("pathlib").getMember(["Path"]).getACall() or
        // io module
        call = API::moduleImport("io").getMember(["open"]).getACall() or
        // built-in file operations
        call = API::moduleImport("builtins").getMember(["open"]).getACall()
      )
    )
  }

  predicate isBarrier(DataFlow::Node node) {
    // Common path validation functions could be barriers
    exists(API::CallNode call |
      call = API::moduleImport("os").getMember("path").getMember(["abspath", "normpath", "realpath", "basename"]).getACall() or
      call = API::moduleImport("pathlib").getMember("Path").getMember(["resolve", "absolute"]).getACall()
    )
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;
import PathTraversalFlow::PathGraph

from PathTraversalFlow::PathNode source, PathTraversalFlow::PathNode sink
where PathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Path traversal vulnerability from $@.", source.getNode(), "user input"
